def to_roman(n: int) -> str:
    """Convert an integer to a Roman numeral string.

    Valid range: 1 <= n <= 3999. Raises ValueError otherwise.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Input must be an integer, got {type(n)}")
    if n < 1 or n > 3999:
        raise ValueError(f"Input must be between 1 and 3999, got {n}")

    val_sym = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'),  (90, 'XC'),  (50, 'L'),  (40, 'XL'),
        (10, 'X'),   (9, 'IX'),   (5, 'V'),   (4, 'IV'),
        (1, 'I'),
    ]

    result = []
    for value, symbol in val_sym:
        while n >= value:
            result.append(symbol)
            n -= value
    return ''.join(result)


def from_roman(s: str) -> int:
    """Convert a Roman numeral string to an integer.

    Input must be a non-empty, canonical, uppercase Roman numeral string.
    Raises ValueError for empty input, non-Roman characters, or non-canonical form.
    """
    if not s:
        raise ValueError("Input must be a non-empty string")

    roman_chars = set('MDCLXVI')
    for ch in s:
        if ch not in roman_chars:
            raise ValueError(f"Invalid character in Roman numeral: {ch!r}")

    # Parse the value
    roman_values = {'M': 1000, 'D': 500, 'C': 100, 'L': 50,
                    'X': 10, 'V': 5, 'I': 1}

    total = 0
    prev = 0
    for ch in reversed(s):
        curr = roman_values[ch]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr

    # Validate canonicality by checking round-trip
    if total < 1 or total > 3999:
        raise ValueError(f"Roman numeral out of valid range: {s!r}")

    if to_roman(total) != s:
        raise ValueError(f"Non-canonical Roman numeral: {s!r}")

    return total
